export interface ConnectorConfig {
  notionApiKey: string
  notionDatabaseId: string
  fetch?: typeof fetch
}

export interface PipedriveDealPayload {
  meta: {
    action: string
    entity: string
    entity_id: string
    timestamp: string
    version: string
  }
  data: {
    id: number
    title: string
    value: number
    owner_id: {
      name: string
    }
    close_date?: string
    won_time?: string
  }
  previous: unknown
}

export interface NotionPageResponse {
  id: string
  object: string
  created_time: string
  last_edited_time: string
}

export interface HandleResult {
  notionPageId: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: unknown): asserts payload is PipedriveDealPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.meta || typeof p.meta !== 'object') {
    throw new Error('Missing required field: meta')
  }
  const meta = p.meta as Record<string, unknown>
  if (meta.action !== 'change' || meta.entity !== 'deal') {
    throw new Error('Webhook is not a deal change event')
  }
  if (!p.data || typeof p.data !== 'object') {
    throw new Error('Missing required field: data')
  }
  const data = p.data as Record<string, unknown>
  if (typeof data.title !== 'string' || !data.title) {
    throw new Error('Missing required field: data.title')
  }
  if (typeof data.value !== 'number') {
    throw new Error('Missing required field: data.value (must be a number)')
  }
  if (!data.owner_id || typeof data.owner_id !== 'object' || typeof (data.owner_id as Record<string, unknown>).name !== 'string') {
    throw new Error('Missing required field: data.owner_id.name')
  }
  if (!data.won_time && !data.close_date) {
    throw new Error('Missing required field: data.won_time or data.close_date')
  }
}

function extractCloseDate(data: PipedriveDealPayload['data']): string {
  if (data.won_time) {
    return data.won_time.split('T')[0]
  }
  return data.close_date!
}

function buildNotionPayload(payload: PipedriveDealPayload, databaseId: string) {
  const closeDate = extractCloseDate(payload.data)
  return {
    parent: {
      database_id: databaseId
    },
    properties: {
      'Deal Title': {
        title: [
          {
            text: {
              content: payload.data.title
            }
          }
        ]
      },
      'Deal Value': {
        number: payload.data.value
      },
      'Deal Owner': {
        rich_text: [
          {
            text: {
              content: payload.data.owner_id.name
            }
          }
        ]
      },
      'Close Date': {
        date: {
          start: closeDate
        }
      }
    }
  }
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)
  const typedPayload = payload as PipedriveDealPayload

  const fetchFn = getFetch(config)
  const notionPayload = buildNotionPayload(typedPayload, config.notionDatabaseId)

  const response = await fetchFn('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.notionApiKey}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28'
    },
    body: JSON.stringify(notionPayload)
  })

  if (!response.ok) {
    throw new Error(`Notion API error: ${response.status} ${response.statusText} at POST https://api.notion.com/v1/pages`)
  }

  const result = await response.json() as NotionPageResponse
  return { notionPageId: result.id }
}

